    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?UserRoleAssignmentUserVO
    {
        if ($value instanceof UserRoleAssignmentUserVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (is_a($value, UserRef::class)) {
            return new UserRoleAssignmentUserVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['user'], [$value], ['UserRef']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): UserRoleAssignmentUserVO
    {
        if ($value instanceof UserRoleAssignmentUserVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof UserRoleAssignmentUserVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
